import React, { useEffect, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Graph = () => {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchCurrentCurrencyValue = async () => {
        try {
            const response = await fetch('http://localhost:8000/current-currency-value');
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            const result = await response.json();
            const currentValue = result.value; // Valor actual del tipo de cambio

            setData(prevData => [
                ...prevData,
                { name: new Date().toLocaleTimeString(), value: currentValue }
            ]);
            setLoading(false);
        } catch (error) {
            console.error('Error fetching currency value:', error.message);
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchCurrentCurrencyValue();
        const intervalId = setInterval(fetchCurrentCurrencyValue, 10000); // Actualiza cada 10 segundos

        return () => clearInterval(intervalId); // Limpia el intervalo al desmontar
    }, []);

    if (loading) {
        return <div>Cargando...</div>; // O un spinner/loading icon
    }

    return (
        <ResponsiveContainer width="100%" height={300}>
            <LineChart data={data}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Line type="monotone" dataKey="value" stroke="#8884d8" />
            </LineChart>
        </ResponsiveContainer>
    );
};

export default Graph;
